// RoomAsset.swift — high-quality ultrawide wallpapers (wallhaven, SFW), cropped to
// 1920x480 and JPEG-embedded. Screensaver backdrops (crisp — sourced high-res, not
// upscaled). Selected/auto-rotated via the Settings picker.

import CoreGraphics
import Foundation
import ImageIO

enum RoomAsset {
    static let names = ["都市小队", "蓝羽", "铃兰", "雪山", "红弦", "甲板"]
    nonisolated(unsafe) static let images: [CGImage] = b64s.compactMap(decode)
    static var count: Int { images.count }

    private static func decode(_ s: String) -> CGImage? {
        guard let d = Data(base64Encoded: s),
              let src = CGImageSourceCreateWithData(d as CFData, nil),
              let img = CGImageSourceCreateImageAtIndex(src, 0, nil) else { return nil }
        return img
    }
